// TH16 v1.00a Stage 4 boss, BossCard2 (st04bs.ecl.txt:578-649), spells 38-41.
// Source entry = timerReset at line 588; source window 2280 frames (setInterrupt slot0).
// Card frame = source frame + 121 (opening buffer 120 + spawn/host startup offset).

const TH16_FIREBALL_RED: int = 752;     // source etSprite type 25, color 0
const TH16_FIREBALL_PURPLE: int = 768;  // source etSprite type 26, color 0

const GVAR_GI0: int = 16;               // source $GI0 (-9926), global shared parent<->golem
const TIME_LIMIT: int = 2404;           // 120 buffer + 2280 source interrupt + 4 startup
const OPENING_BUFFER: int = 120;

// st04bs.ecl.txt:757-761 (emitter 0): VELTIME a=120 r=0 keeps angle, WAIT 20, DELETE.
// ANIM(2,1)/BRIGHT are the approved-omitted birth presentation; their 4*velocity retreat
// is kept in the emitter's sh_dist below.
xformdef CARD2_AT_BULLET {
    @120 step_speed(0fx, 120);          // VELTIME: scalar speed -> 0 over 120 frames
    wait(20);                           // WAIT a=20, cursor only
    set_life(1);                        // DELETE
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(60); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(60); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Inherited Boss2 position is not handed over; the source's first action (line 613)
    // wins the position to (0,128), so the isolated card starts there.
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
}

// Real boss. Body hitbox from Boss context (st04bs.ecl.txt:27-28 setHurtbox(40,40),
// setHitbox(48,48)); invincible per the approved training shell.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // line 613: movePosTime(60, 4, 0, 128) - zero displacement from the start point.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);                          // line 618 "+120"
    // lines 620-623: %F0=64 inherited by the child (constant here), %GF0=1.0,
    // %I0=$LAST_ENM_ID is never read back, so only the shared GI0 channel is kept.
    _ = spawn_enemy($self_x, $self_y, 1000, 0, 0, 0, golem($self_enemy));

    // lines 626-642: GI0=0 for 450 frames, GI0=1 for 120 frames; cycle 570 frames.
    for cycle in 0..3 {
        set_global(GVAR_GI0, 0);
        wait(300);                      // line 630
        card_move_rand();               // line 631 moveRand(60,4,1.0)
        card_wait(60);                  // line 632
        card_wait(90);                  // line 638
        set_global(GVAR_GI0, 1);        // line 639
        card_wait(120);                 // line 640
    }
    // 4th cycle cut by the source interrupt: 120 + 3*570 + (300+60+90) = 2280.
    set_global(GVAR_GI0, 0);
    wait(300);
    card_move_rand();
    card_wait(60);
    card_wait(90);
    // line 607 setInterrupt(0,0,2280,"Boss3"): BossCard2 returns here; boss exits (D9).
}

// moveRand helper, movement.md recipe with this card's limit (0,128,240,64) and speed 1.0:
// per-step speed 1-k/60, hard clamp x[-120,120] y[96,160], direction inner box x±60, y112..144.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// BossCard2Bomb (651-679): child at the boss position, hitbox grows to %F0=64 over 20
// frames and stays (deathAnm/anmScale/playSound are presentation).
async sub golem(boss: int) {
    set_invuln(65535);
    spawn bomb_move(boss);              // line 660 async
    spawn bomb_at();                    // line 661 async
    var c: fx = 0fx;                    // line 662
    for i in 0..20 {                    // line 663 $D=20
        set_hurtbox(c / 6fx);           // line 666 setHurtbox(C/3, C), circle half-width
        set_hitbox(c * 0.5fx);          // line 667 setHitbox(C, C) -> radius C/2
        c = c + 64fx / 12fx;            // line 668 %C += %F0/12
        wait(1);
    }
    // line 672 %F1 is never read; source then waits forever. Tied to the boss so the
    // standalone card's child leaves with the card instead of firing past its end.
    while enemy_alive(boss) == 1 {
        wait(1);
    }
}

// BossCard2BombMove (690-715): chase the player at %GF0=1, re-aim every 10 frames while
// GI0==0; while GI0!=0 return to the boss's current position (mode 9 = QUAD_IN_OUT).
async sub bomb_move(boss: int) {
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);            // line 693
    move_vel(60, aim_player(), 1fx, EASE_LINEAR);           // line 694
    wait(60);                                               // line 695
    var guard: int = 10000;                                 // line 696
    loop {
        if global(GVAR_GI0) == 0 {                          // line 699
            move_vel(10, aim_player(), 1fx, EASE_LINEAR);   // line 700
            wait(10);                                       // line 701
        } else {
            var bx: fx = $self_x;
            var by: fx = $self_y;
            if enemy_alive(boss) == 1 {                     // line 705 %BOSS_X/%BOSS_Y
                bx = enemy_x(boss);
                by = enemy_y(boss);
            }
            move_to(120, bx, by, EASE_QUAD_IN_OUT);         // line 705 movePosTime(120,9,..)
            wait(120);                                      // line 706
        }
        guard = guard - 1;                                  // line 708 if ($A--)
        if guard <= 0 { break; }
    }
    loop { wait(1000); }                                    // lines 710-714
}

// BossCard2_at (730-808): emitter 0 sweeps a counter-rotating pair of rings; emitter 1
// fires a random-angle ring while GI0==1 on Normal+ (source !NHL).
async sub bomb_at() {
    var rank: int = global(GVAR_RANK);
    var count0: int = 1;                // 736-743: E1 N1 H2 LO3
    var speed0: fx = 3fx;               // 747-754: E3.0 N3.0 H3.5 LO3.5
    var period: int = 10;               // 790-797: E10 N10 H8 LO10
    var count1: int = 10;               // 765-772: E10 N10 H16 LO16
    var dist0: fx = 52fx;               // etDist 64 - ANIM retreat 4*3.0
    var ring1: int = 0;
    if rank >= RANK_LUNATIC {
        count0 = 3; speed0 = 3.5fx; period = 10; count1 = 16; dist0 = 50fx; ring1 = 1;
    } else if rank >= RANK_HARD {
        count0 = 2; speed0 = 3.5fx; period = 8; count1 = 16; dist0 = 50fx; ring1 = 1;
    } else if rank >= RANK_NORMAL {
        ring1 = 1;
    }

    sh_reset(0);
    sh_sprite(0, TH16_FIREBALL_RED, 0);     // 734 type 25 color 0
    sh_ring(0, 1);                          // 733 etAim(0,3) fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, count0, 1);
    sh_speed(0, speed0, 0fx);
    sh_dist(0, dist0);                      // 779 etDist(0,64) combined with ANIM retreat
    sh_xform(0, CARD2_AT_BULLET);

    sh_reset(1);
    sh_sprite(1, TH16_FIREBALL_PURPLE, 0);  // 764 type 26 color 0
    sh_ring(1, 1);                          // 763 etAim(1,3)
    sh_aim(1, 0);
    sh_count(1, count1, 1);
    sh_speed(1, 2fx, 0fx);                  // 776 etSpeed(1,2.0,1.0), 1 layer
    sh_dist(1, -8fx);                       // no etDist; ANIM retreat 4*2.0 backwards

    var a: angle = 90deg;                   // 780-781
    var b: angle = 90deg;
    loop {
        a = a + 10deg;                      // 784 0.174533 rad
        sh_angle(0, a, 0deg);
        sh_fire(0);                         // 786
        b = b - 10deg;                      // 787
        sh_angle(0, b, 0deg);
        sh_fire(0);                         // 789
        wait(period);                       // 799
        if global(GVAR_GI0) == 1 && ring1 == 1 {
            sh_angle(1, rand(65536) as angle, 0deg);  // 802 %RANDRAD, one sample per wave
            sh_fire(1);                     // 803
        }
    }
}
